        t=n.get('type') or n.get('elementType') or ''
        lab=n.get('label','')
        val=n.get('value','')
        ph=n.get('placeholder','')
        ident=n.get('identifier','')
        fr=n.get('frame') or n.get('rect') or {}
        ed=n.get('editable') or n.get('isEditable')
        foc=n.get('focused') or n.get('hasFocus')
        line=f\"{'  '*depth}{t} label={lab!r} val={val!r} ph={ph!r} id={ident!r}\"
        if ed: line+=' [editable]'
